import {
  Callout,
  Code,
  Divider,
  Grid,
  H1,
  H2,
  H3,
  Pill,
  Row,
  Stack,
  Table,
  Text,
  useHostTheme,
} from "cursor/canvas";

interface CascadeStep {
  cond: string;
  out: string;
  note: string;
  tone: "hit" | "gap" | "normal";
}

const CASCADE: CascadeStep[] = [
  {
    cond: "Specialbranchid = 'BDGV'",
    out: "1.00",
    note: "Nhánh đè lên tất cả",
    tone: "normal",
  },
  {
    cond: "TrainingLevelID = 'C'   và   SubjectName là môn đại cương",
    out: "0.93",
    note: "Hai dòng C49CNOTA / C49CNTT-Đ-ANH-NHAT PL trúng nhánh này",
    tone: "hit",
  },
  {
    cond: "TrainingLevelID = 'T'   và   SubjectName là môn đại cương",
    out: "0.82",
    note: "Chưa có dòng nào trúng",
    tone: "normal",
  },
  {
    cond: "TrainingLevelID = 'C'",
    out: "1.00",
    note: "Cao đẳng, môn không phải đại cương",
    tone: "normal",
  },
  {
    cond: "TrainingLevelID = 'T'",
    out: "0.88",
    note: "Trung cấp, môn không phải đại cương",
    tone: "normal",
  },
  {
    cond: "TrainingLevelID = '5'",
    out: "0.63",
    note: "Văn hóa phổ thông",
    tone: "normal",
  },
  {
    cond: "TrainingLevelID trong ('S', 'TT', 'N', 'BDCD', 'TX')",
    out: "0.78",
    note: "Các hệ bồi dưỡng / sơ cấp",
    tone: "normal",
  },
  {
    cond: "Else — mọi mã còn lại",
    out: "1.00",
    note: "Ba dòng C49GDMNBCDEQ_Pháp luật_1/2/3 rơi vào đây",
    tone: "gap",
  },
];

const DECISION_TITLE =
  "HeSo  =  Case ... End   (trả về đúng một giá trị cho mỗi dòng)";

const FLOW_TITLE =
  "Sơ đồ chuỗi quyết định sinh ra cột HeSo trong store SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New";

function FlowDiagram() {
  const theme = useHostTheme();
  const boxX = 40;
  const boxW = 600;
  const boxH = 52;
  const gapY = 16;
  const startY = 76;
  const outX = 692;
  const outW = 150;
  const height = 632;

  const stepTop = (index: number) => startY + index * (boxH + gapY);
  const stepMid = (index: number) => stepTop(index) + boxH / 2;

  return (
    <div style={{ overflowX: "auto" }}>
      <svg
        viewBox={`0 0 900 ${height}`}
        width="100%"
        style={{ minWidth: 720, display: "block" }}
        role="img"
        aria-label={FLOW_TITLE}
      >
        <rect
          x={boxX}
          y={20}
          width={boxW}
          height={36}
          rx={6}
          fill={theme.fill.tertiary}
          stroke={theme.stroke.secondary}
        />
        <text
          x={boxX + boxW / 2}
          y={42}
          textAnchor="middle"
          fontSize={12}
          fontWeight={590}
          fill={theme.text.primary}
        >
          {DECISION_TITLE}
        </text>
        <line
          x1={boxX + boxW / 2}
          y1={56}
          x2={boxX + boxW / 2}
          y2={startY}
          stroke={theme.stroke.primary}
          strokeWidth={1}
        />
        {CASCADE.map((step, index) => {
          const isHit = step.tone === "hit";
          const isGap = step.tone === "gap";
          const accent = theme.accent.primary;
          const neutralStroke = theme.stroke.secondary;
          const boxStroke = isHit || isGap ? accent : neutralStroke;
          const boxFill = isHit || isGap ? theme.fill.primary : theme.fill.quaternary;
          const titleTag =
            index === CASCADE.length - 1 ? "Else" : "When " + (index + 1);
          return (
            <g key={step.cond}>
              {index < CASCADE.length - 1 ? (
                <line
                  x1={boxX + boxW / 2}
                  y1={stepTop(index) + boxH}
                  x2={boxX + boxW / 2}
                  y2={stepTop(index + 1)}
                  stroke={theme.stroke.primary}
                  strokeWidth={1}
                />
              ) : null}
              {index < CASCADE.length - 1 ? (
                <text
                  x={boxX + boxW / 2 + 8}
                  y={stepTop(index) + boxH + gapY / 2 + 3}
                  fontSize={10}
                  fill={theme.text.quaternary}
                >
                  Không
                </text>
              ) : null}
              <rect
                x={boxX}
                y={stepTop(index)}
                width={boxW}
                height={boxH}
                rx={6}
                fill={boxFill}
                stroke={boxStroke}
              />
              <text
                x={boxX + 12}
                y={stepTop(index) + 21}
                fontSize={10}
                fontWeight={590}
                fill={isHit || isGap ? accent : theme.text.quaternary}
              >
                {titleTag}
              </text>
              <text
                x={boxX + 12}
                y={stepTop(index) + 39}
                fontSize={12}
                fill={theme.text.primary}
              >
                {step.cond}
              </text>
              <line
                x1={boxX + boxW}
                y1={stepMid(index)}
                x2={outX - 8}
                y2={stepMid(index)}
                stroke={boxStroke}
                strokeWidth={1}
              />
              <polygon
                points={`${outX - 8},${stepMid(index) - 4} ${outX},${stepMid(index)} ${outX - 8},${stepMid(index) + 4}`}
                fill={boxStroke}
              />
              <text
                x={boxX + boxW + 8}
                y={stepMid(index) - 8}
                fontSize={10}
                fill={theme.text.quaternary}
              >
                Đúng
              </text>
              <rect
                x={outX}
                y={stepMid(index) - 16}
                width={outW}
                height={32}
                rx={6}
                fill={boxFill}
                stroke={boxStroke}
              />
              <text
                x={outX + outW / 2}
                y={stepMid(index) + 5}
                textAnchor="middle"
                fontSize={13}
                fontWeight={590}
                fill={isHit || isGap ? accent : theme.text.primary}
              >
                {step.out}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}

const ROWS_5: (string | number)[][] = [
  ["5818000084188", "C49CNOTA", "60022", "C", "0.93"],
  ["5818000084209", "C49GDMNBCDEQ_Pháp luật_1", "6GDMN0152", "1 ", "1.00"],
  ["5818000084210", "C49GDMNBCDEQ_Pháp luật_2", "6GDMN0152", "1 ", "1.00"],
  ["5818000084211", "C49GDMNBCDEQ_Pháp luật_3", "6GDMN0152", "1 ", "1.00"],
  ["5818000084248", "C49CNTT-Đ-ANH-NHAT PL", "60022", "C", "0.93"],
];

const ROWS_5_BRANCH: (string | number)[] = [
  "When 2 — TrainingLevelID = 'C' + môn đại cương",
  "Else — mã '1 ' không khớp nhánh nào",
  "Else — mã '1 ' không khớp nhánh nào",
  "Else — mã '1 ' không khớp nhánh nào",
  "When 2 — TrainingLevelID = 'C' + môn đại cương",
];

const ROW_TONE_5: ("warning" | undefined)[] = [
  undefined,
  "warning",
  "warning",
  "warning",
  undefined,
];

interface CatalogRow {
  code: string;
  name: string;
  level: string;
  branch: string;
  covered: boolean;
  daiCuong: string;
  khac: string;
}

const CATALOG: CatalogRow[] = [
  { code: "0", name: "(chưa đặt tên)", level: "3", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "1 ", name: "Cao đẳng (đào tạo giáo viên)", level: "3", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "2 ", name: "Cao đẳng SP (LT - VLVH)", level: "3", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "3 ", name: "Cao đẳng Liên thông", level: "3", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "4 ", name: "Trung cấp (lĩnh vực GDNN)", level: "2", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "5 ", name: "Văn hóa phổ thông", level: "2", branch: "= '5'", covered: true, daiCuong: "0.63", khac: "0.63" },
  { code: "6 ", name: "Trung cấp SP (VLVH)", level: "2", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "7 ", name: "Cao đẳng (lĩnh vực GDNN)", level: "3", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "8 ", name: "Cao đẳng GDNN (LT - VLVH)", level: "3", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "9 ", name: "Trung cấp (01 năm học)", level: "2", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "A ", name: "Sơ cấp", level: "1", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "BDCD", name: "Bồi dưỡng chức danh nghề nghiệp", level: "7", branch: "trong nhóm 0.78", covered: true, daiCuong: "0.78", khac: "0.78" },
  { code: "C", name: "Cao đẳng", level: "3", branch: "= 'C'", covered: true, daiCuong: "0.93", khac: "1.00" },
  { code: "CLT", name: "Cao đẳng liên thông", level: "3", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "N ", name: "Bồi dưỡng nghiệp vụ lĩnh vực GDNN", level: "1", branch: "trong nhóm 0.78", covered: true, daiCuong: "0.78", khac: "0.78" },
  { code: "S", name: "Sơ cấp", level: "1", branch: "trong nhóm 0.78", covered: true, daiCuong: "0.78", khac: "0.78" },
  { code: "SS", name: "Bồi dưỡng giáo viên", level: "1", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "T", name: "Trung cấp", level: "2", branch: "= 'T'", covered: true, daiCuong: "0.82", khac: "0.88" },
  { code: "TCN", name: "Trung cấp nghề", level: "3", branch: "Else", covered: false, daiCuong: "1.00", khac: "1.00" },
  { code: "TT", name: "Bồi dưỡng Ngôn ngữ", level: "1", branch: "trong nhóm 0.78", covered: true, daiCuong: "0.78", khac: "0.78" },
  { code: "TX", name: "Đào tạo thường xuyên", level: "1", branch: "trong nhóm 0.78", covered: true, daiCuong: "0.78", khac: "0.78" },
];

function CatalogCell({ row }: { row: CatalogRow }) {
  const theme = useHostTheme();
  const showTrailingSpace = row.code.endsWith(" ");
  return (
    <Row gap={6} align="center">
      <Code>{showTrailingSpace ? `'${row.code}'` : row.code}</Code>
      {showTrailingSpace ? (
        <span style={{ color: theme.text.quaternary, fontSize: 11 }}>
          có khoảng trắng cuối
        </span>
      ) : null}
    </Row>
  );
}

export default function HeSoBangTinhGio() {
  const theme = useHostTheme();
  const coveredCodes = CATALOG.filter((row) => row.covered).length;

  return (
    <Stack gap={20} style={{ padding: 24, background: theme.bg.editor }}>
      <Stack gap={8}>
        <H1>Vì sao cùng môn “Pháp luật” mà cột Hệ số khác nhau</H1>
        <Text tone="secondary">
          Cột Hệ số trên lưới Bảng tính giờ dạy giảng viên lấy nguyên từ store{" "}
          <Code>SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New</Code>. Form không tự
          tính giá trị này. Chênh lệch 0.93 và 1.00 nằm hoàn toàn trong chuỗi{" "}
          <Code>Case ... End</Code> của store.
        </Text>
        <Row gap={8} wrap>
          <Pill active>GV NG120 — Mai Hồng Quyên</Pill>
          <Pill>5 dòng — HP 60022 và 6GDMN0152</Pill>
          <Pill>{`Mã bậc được phủ: ${coveredCodes}/${CATALOG.length}`}</Pill>
        </Row>
      </Stack>

      <Divider />

      <Stack gap={10}>
        <H2>Sơ đồ chuỗi quyết định</H2>
        <Text tone="secondary" size="small">
          Đọc từ trên xuống. Mỗi điều kiện được xét theo thứ tự; dòng dữ liệu dừng ở
          điều kiện Đúng đầu tiên và nhận đúng hệ số của nhánh đó. Ô vạch màu accent là
          hai nhánh quyết định kết quả 5 dòng đang xét.
        </Text>
        <FlowDiagram />
        <Text tone="tertiary" size="small">
          Nguồn: nhánh Case When / Then trong store{" "}
          <Code>SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New</Code>, bước 7 “Kết quả”.
        </Text>
      </Stack>

      <Divider />

      <Stack gap={10}>
        <H2>Áp vào 5 dòng dữ liệu thực tế</H2>
        <Text tone="secondary" size="small">
          Cả 5 dòng đều có SubjectName khớp đúng chuỗi{" "}
          <Code>N&apos;Pháp luật&apos;</Code>. Khác biệt duy nhất là{" "}
          <Code>TrainingLevelID</Code>.
        </Text>
        <Table
          headers={[
            "ClassSubjectID",
            "ClassID",
            "SubjectID",
            "TrainingLevelID",
            "Nhánh trúng",
            "HeSo",
          ]}
          columnAlign={["left", "left", "left", "left", "left", "right"]}
          rowTone={ROW_TONE_5}
          striped
          rows={ROWS_5.map((row, index) => [
            <Code key={row[0] as string}>{row[0]}</Code>,
            row[1],
            <Code key={`${row[2]}-${index}`}>{row[2]}</Code>,
            <Code key={`tl-${index}`}>{`'${row[3]}'`}</Code>,
            ROWS_5_BRANCH[index],
            row[4],
          ])}
        />
      </Stack>

      <Grid columns={2} gap={12}>
        <Callout tone="info" title="Nhóm 0.93 — lớp C49CNOTA và C49CNTT-Đ-ANH-NHAT PL">
          <Text size="small">
            <Code>TrainingLevelID = &apos;C&apos;</Code> (Cao đẳng) và môn đại cương,
            nên trúng đúng nhánh <Code>When 2</Code> và nhận 0.93.
          </Text>
        </Callout>
        <Callout tone="warning" title="Nhóm 1.00 — 3 lớp C49GDMNBCDEQ_Pháp luật">
          <Text size="small">
            <Code>TrainingLevelID = &apos;1 &apos;</Code> — mã Cao đẳng (đào tạo giáo
            viên). Store không có nhánh nào cho mã này nên rơi xuống{" "}
            <Code>Else</Code> và nhận 1.00, dù vẫn là Cao đẳng và vẫn là môn đại cương.
          </Text>
        </Callout>
      </Grid>

      <Divider />

      <Stack gap={10}>
        <H2>Danh mục SIM_TrainingLevel — mã nào được store phủ</H2>
        <Text tone="secondary" size="small">
          Cột “Nhánh store” cho biết mã bậc đó rơi vào nhánh nào. Hai cột hệ số cuối là
          kết quả thực tế: cột trước cho môn đại cương, cột sau cho môn thường. Ô bôi
          vàng là mã chưa được phủ.
        </Text>
        <Table
          headers={[
            "TrainingLevelID",
            "TrainingLevelName",
            "LearningLevel",
            "Nhánh store",
            "Hệ số môn đại cương",
            "Hệ số môn khác",
          ]}
          columnAlign={["left", "left", "left", "left", "right", "right"]}
          rowTone={CATALOG.map((row) => (row.covered ? undefined : "warning"))}
          striped
          rows={CATALOG.map((row) => [
            <CatalogCell key={row.code} row={row} />,
            row.name,
            row.level,
            row.branch,
            row.daiCuong,
            row.khac,
          ])}
        />
      </Stack>

      <Stack gap={10}>
        <H3>Hai lỗ hổng cần vá</H3>
        <Stack gap={10}>
          <Callout tone="warning" title="1. Store chỉ biết các mã bậc cũ">
            <Text size="small">
              Chuỗi <Code>Case</Code> chỉ xử lý <Code>&apos;C&apos;</Code>,{" "}
              <Code>&apos;T&apos;</Code>, <Code>&apos;5&apos;</Code> và nhóm{" "}
              <Code>&apos;S&apos;, &apos;TT&apos;, &apos;N&apos;, &apos;BDCD&apos;,
              &apos;TX&apos;</Code>. Toàn bộ mã Cao đẳng mới như{" "}
              <Code>&apos;1&apos;</Code>, <Code>&apos;2&apos;</Code>,{" "}
              <Code>&apos;3&apos;</Code>, <Code>&apos;7&apos;</Code>,{" "}
              <Code>&apos;8&apos;</Code>, <Code>&apos;CLT&apos;</Code> đều rơi{" "}
              <Code>Else</Code> nên môn đại cương của các hệ này không được 0.93. Tương
              tự, các mã Trung cấp mới <Code>&apos;4&apos;</Code>,{" "}
              <Code>&apos;6&apos;</Code>, <Code>&apos;9&apos;</Code> không được 0.82.
            </Text>
          </Callout>
          <Callout tone="warning" title="2. Mã bậc có khoảng trắng cuối">
            <Text size="small">
              Nhiều dòng danh mục lưu mã kèm khoảng trắng: <Code>&apos;1 &apos;</Code>,{" "}
              <Code>&apos;N &apos;</Code>, <Code>&apos;2 &apos;</Code>… Phép so sánh
              chuỗi trong store là so khớp tuyệt đối, nên <Code>&apos;1 &apos;</Code>{" "}
              khác <Code>&apos;1&apos;</Code> và bị trượt. Cần so qua{" "}
              <Code>Ltrim(Rtrim(...))</Code> hoặc chuẩn hoá lại danh mục.
            </Text>
          </Callout>
          <Callout tone="info" title="Ghi chú: hai danh sách loại trừ không khớp nhau">
            <Text size="small">
              Store dùng danh sách 0.78 gồm 5 mã{" "}
              <Code>&apos;S&apos;, &apos;TT&apos;, &apos;N&apos;, &apos;BDCD&apos;,
              &apos;TX&apos;</Code>, còn C# trong form dùng danh sách 7 mã, thêm{" "}
              <Code>&apos;A&apos;</Code> và <Code>&apos;SS&apos;</Code>. Vì vậy lớp{" "}
              <Code>&apos;A &apos;</Code> và <Code>&apos;SS&apos;</Code> được hệ số lớp
              1.00 nhưng hệ số môn lại 1.00 qua nhánh <Code>Else</Code> thay vì 0.78.
            </Text>
          </Callout>
        </Stack>
      </Stack>

      <Divider />

      <Stack gap={8}>
        <H3>Lưu ý về patch lấy dữ liệu theo lớp gốc</H3>
        <Text tone="secondary" size="small">
          Patch <Code>20261006_SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New_fix_heso_lop_goc.sql</Code>{" "}
          sửa việc lớp tách/ghép lấy nhầm <Code>TrainingLevelID</Code> của dòng{" "}
          <Code>SIM_Class</Code> logic. Patch này cần thiết để dữ liệu nhất quán, nhưng{" "}
          <Text weight="semibold">chưa chắc đã đổi được 1.00 thành 0.93</Text>, vì lớp
          gốc <Code>C49GDMNBCDEQ</Code> cũng có thể đang mang mã <Code>&apos;1 &apos;</Code>.
        </Text>
        <Text tone="secondary" size="small">
          Chạy query sau để xác nhận trước khi quyết định sửa store hay sửa danh mục:
        </Text>
        <div
          style={{
            background: theme.fill.quaternary,
            border: `1px solid ${theme.stroke.tertiary}`,
            borderRadius: 6,
            padding: 12,
            overflowX: "auto",
          }}
        >
          <pre
            style={{
              margin: 0,
              fontSize: 11,
              lineHeight: "17px",
              color: theme.text.primary,
            }}
          >
{`Select
	SIM_Class.ClassID,
	SIM_Class.ClassType,
	SIM_Class.ClassSubjectID,
	SIM_Class.TrainingLevelID,
	Len(SIM_Class.TrainingLevelID) As DoDaiTL
From SIM_Class
Where SIM_Class.ClassID In ('C49GDMNBCDEQ', 'C49GDMNBCDEQ_Pháp luật_1')
	or SIM_Class.ClassType = 2
Order By SIM_Class.ClassID`}
          </pre>
        </div>
      </Stack>
    </Stack>
  );
}
